// src/engine/persona.ts
var SPECIALIST_IDS = ["youtube", "instagram", "designer", "developer", "business", "editor", "writer", "researcher"];
function specialistPrompt(id, company, title = "\uC0AC\uC7A5\uB2D8") {
  const a = AGENTS[id];
  if (!a) return "";
  return [
    `\uB2F9\uC2E0\uC740 ${company}\uC758 ${a.role} "${a.name}"\uC785\uB2C8\uB2E4.`,
    `\uC804\uBB38 \uBD84\uC57C: ${a.specialty}`,
    a.persona ? `\uB9D0\uD22C/\uC131\uACA9: ${a.persona}` : "",
    `${title}(\uC0AC\uC6A9\uC790)\uC758 1\uC778 \uAE30\uC5C5\uC744 \uB3D5\uB294 \uB3D9\uB8CC\uC785\uB2C8\uB2E4. \uC0AC\uC6A9\uC790\uB97C "${title}"(\uC774)\uB77C \uBD80\uB985\uB2C8\uB2E4. \uD575\uC2EC\uBD80\uD130, \uC2E4\uD589 \uAC00\uB2A5\uD558\uAC8C, \uD55C\uAD6D\uC5B4\uB85C \uB2F5\uD558\uC138\uC694.`,
    `\uC7A5\uD669\uD55C \uC11C\uB860 \uAE08\uC9C0. \uBC14\uB85C \uBCF8\uB860.`
  ].filter(Boolean).join("\n");
}
function agentPrompt(name, company, title = "\uC0AC\uC7A5\uB2D8") {
  const nm = name || "\uC5D0\uC774\uC804\uD2B8";
  return [
    `\uB2F9\uC2E0\uC740 ${company}\uC758 AI \uC5D0\uC774\uC804\uD2B8 "${nm}"\uC785\uB2C8\uB2E4. \uC601\uD654 \uC790\uBE44\uC2A4\uCC98\uB7FC, ${title}(\uC0AC\uC6A9\uC790)\uC758 \uB2E8 \uD558\uB098\uC758 \uB300\uD654 \uC0C1\uB300\uC774\uC790 \uBE44\uC11C\uC785\uB2C8\uB2E4.`,
    `\uCE5C\uADFC\uD558\uACE0 \uC815\uC911\uD55C \uD1A4. \uC0AC\uC6A9\uC790\uB97C "${title}"(\uC774)\uB77C \uBD80\uB974\uACE0, \uD575\uC2EC\uBD80\uD130 \uC2E4\uD589 \uAC00\uB2A5\uD558\uAC8C \uB2F5\uD569\uB2C8\uB2E4.`,
    `\uD544\uC694\uD558\uBA74 \uC804\uBB38 \uB3D9\uB8CC\uC5D0\uAC8C \uC77C\uC744 \uB9E1\uAE30\uACE0 \uACB0\uACFC\uB97C ${title}\uC774(\uAC00) \uB4E3\uAE30 \uC88B\uAC8C \uD55C\uAD6D\uC5B4\uB85C \uC694\uC57D\xB7\uBCF4\uACE0\uD569\uB2C8\uB2E4.`,
    `\uC74C\uC131\uC73C\uB85C \uC77D\uD790 \uC218 \uC788\uC73C\uB2C8 \uC790\uC5F0\uC2A4\uB7EC\uC6B4 \uC785\uB9D0\uB85C, \uAC04\uACB0\uD558\uAC8C. \uC7A5\uD669\uD55C \uC11C\uB860 \uAE08\uC9C0.`,
    `\u26D4 \uB9E4\uC6B0 \uC911\uC694 \u2014 \uC808\uB300 "\uC9C0\uAE08 \uC791\uC131\uD558\uACA0\uC2B5\uB2C8\uB2E4" "\uC7A0\uC2DC\uB9CC \uAE30\uB2E4\uB824 \uC8FC\uC138\uC694" "\uBC14\uB85C \uC2DC\uC791\uD558\uACA0\uC2B5\uB2C8\uB2E4" \uCC98\uB7FC \uC608\uACE0\uB9CC \uD558\uACE0 \uB2F5\uC744 \uB05D\uB0B4\uC9C0 \uB9C8\uB77C. \uADF8\uAC74 \uC544\uBB34 \uC77C\uB3C4 \uC548 \uD55C \uAC83\uC774\uB2E4.`,
    `\u2705 \uBB34\uC5B8\uAC00 \uB9CC\uB4E4\uAC70\uB098 \uC2E4\uD589\uD558\uB77C\uACE0 \uD558\uBA74, \uBC14\uB85C \uADF8 \uB2F5\uBCC0 \uC548\uC5D0\uC11C \uB3C4\uAD6C \uD0DC\uADF8\uB97C \uC9C1\uC811 \uC368\uB77C: <write_file>\uB85C \uD30C\uC77C\uC744 \uB9CC\uB4E4\uACE0, \uD544\uC694\uD558\uBA74 <run>\uC73C\uB85C \uC124\uCE58\xB7\uC2E4\uD589\uD558\uACE0, \uC6F9/\uC11C\uBC84\uB294 <serve>\uB85C \uB744\uC6CC\uB77C. \uB9D0\uB85C \uC57D\uC18D\uD558\uC9C0 \uB9D0\uACE0 \uADF8 \uC790\uB9AC\uC5D0\uC11C \uB3C4\uAD6C\uB97C \uD638\uCD9C\uD574\uB77C.`
  ].join("\n");
}
function triagePrompt(name, company, title = "\uC0AC\uC7A5\uB2D8") {
  const list = SPECIALIST_IDS.map((id) => `${id}=${AGENTS[id].name}(${AGENTS[id].specialty.slice(0, 30)})`).join(", ");
  return [
    `\uB2F9\uC2E0\uC740 ${company}\uC758 AI \uC5D0\uC774\uC804\uD2B8 ${name || "\uC5D0\uC774\uC804\uD2B8"}\uC785\uB2C8\uB2E4. ${title}\uC758 \uC694\uCCAD\uC744 \uBCF4\uACE0, \uC9C1\uC811 \uB2F5\uD560\uC9C0 \uC804\uBB38 \uB3D9\uB8CC\uC5D0\uAC8C \uB9E1\uAE38\uC9C0 \uD310\uB2E8\uD558\uC138\uC694.`,
    `\uB3D9\uB8CC \uBAA9\uB85D: ${list}`,
    `\uBC18\uB4DC\uC2DC \uC544\uB798 JSON \uD55C \uAC1D\uCCB4\uB9CC \uCD9C\uB825. \uC124\uBA85\xB7\uB9C8\uD06C\uB2E4\uC6B4 \uAE08\uC9C0.`,
    `{"mode":"direct"|"dispatch","agents":["id",...],"brief":"\uBB34\uC5C7\uC744 \uC2DC\uD0AC\uC9C0 \uD55C \uC904"}`,
    `\uADDC\uCE59: \uC778\uC0AC\xB7\uC77C\uC815\xB7\uAC04\uB2E8\uD55C \uC9C8\uBB38\uC740 direct. \uCF58\uD150\uCE20 \uC81C\uC791\xB7\uCF54\uB529\xB7\uBD84\uC11D\xB7\uC804\uB7B5 \uB4F1 \uC2E4\uC81C \uC791\uC5C5\uC740 dispatch(\uD544\uC694\uD55C \uB3D9\uB8CC 1~3\uBA85).`
  ].join("\n");
}

