const PH={planning:'\u{1F50D} \uBD84\uC11D \uC911\u2026',review:'\u2611\uFE0F \uC791\uC804\uC744 \uACE8\uB77C\uC8FC\uC138\uC694',executing:'\u26A1 \uC2E4\uD589 \uC911\u2026',done:'\u{1F3C1} \uC0AC\uC774\uD074 \uC644\uB8CC',idle:'\uB300\uAE30'};
