    F.style.display='';F.innerHTML=(ops.feed||[]).slice(0,8).map(f=>'<div>'+esc(f.icon||'\u{1F527}')+' '+esc(f.text||'')+'</div>').join('');
    $('goB').textContent='\u26A1 \uC2E4\uD589 \uC911\u2026';
