      phase: s.phase || "idle",
      cycle: s.cycle || 0,
      summary: (s.summary || "").slice(0, 160),
      executingTitle: (s.executingTitle || "").slice(0, 80),
      actions: (s.actions || []).slice(0, 8).map((a) => ({ title: a.title, assignee: a.assignee || "agent", risk: a.risk || "safe" })),
      shipped: (s.shipped || []).slice(0, 8).map((x) => ({ title: x.title, ok: !!x.ok, artifacts: (x.artifacts || []).slice(0, 5) })),
      feed: (s.feed || []).slice(0, 8).map((f) => ({ icon: f.icon, text: f.text }))
