    const humans = chosen.filter((a) => a.assignee === "human");
    for (const h of humans) {
      addTask(h.title, { owner: "user", agentEmoji: "\u{1F64B}", priority: "high" });
      const ship = { title: h.title, agent: "human", artifacts: ["\u{1F4CB} \uC0AC\uC7A5\uB2D8 \uD560 \uC77C\uB85C \uB4F1\uB85D"], files: [], ok: true, result: "\uD0DC\uC2A4\uD06C \uBCF4\uB4DC\uC5D0 \uB4F1\uB85D\uD588\uC5B4\uC694 \u2014 \uC0AC\uC7A5\uB2D8\uC774 \uC9C1\uC811 \uC9C4\uD589\uD574 \uC8FC\uC138\uC694", ts: Date.now() };
      opsState.shipped.unshift(ship);
      batch.push(ship);
      opsState.feed.unshift({ icon: "\u{1F64B}", text: `\uC0AC\uC7A5\uB2D8 \uD560 \uC77C \uB4F1\uB85D: ${h.title.slice(0, 44)}`, agent: "secretary", ok: true, ts: Date.now() });
    }
    if (humans.length) {
      opsEmit();
      tgSend(`\u{1F64B} \uC0AC\uC7A5\uB2D8 \uBAAB \uD560 \uC77C ${humans.length}\uAC1C\uAC00 \uB4F1\uB85D\uB410\uC5B4\uC694:
${humans.map((h) => `\u25A1 ${h.title}`).join("\n")}`).catch(() => void 0);
    }
