var monFile = () => path6.join(import_electron.app.getPath("userData"), "monitor.json");
var monBusy = false;
async function monitorTick() {
  const c = loadConfig();
  if (c.monitorOn === false) return;
  if (!c.telegramToken || !c.telegramChatId) return;
  if (monBusy) return;
  monBusy = true;
  try {
    let prev = {};
    try {
      prev = JSON.parse(fs8.readFileSync(monFile(), "utf8"));
    } catch {
    }
    const next = { t: Date.now() };
    const alerts = [];
    const fmt = (n) => Math.round(n).toLocaleString();
    const y = connOf("youtube");
    if (y.YOUTUBE_API_KEY && y.YOUTUBE_CHANNEL_ID) {
      const yt = await fetchChannel(y.YOUTUBE_API_KEY, y.YOUTUBE_CHANNEL_ID).catch(() => null);
      if (yt?.ok && yt.channel) {
        next.ytSubs = yt.channel.subs;
        next.ytViews = yt.channel.views;
        if (prev.ytSubs != null && next.ytSubs !== prev.ytSubs) {
          const d = next.ytSubs - prev.ytSubs;
          alerts.push(`\u{1F4FA} \uAD6C\uB3C5\uC790 ${d > 0 ? "+" : ""}${fmt(d)} \u2192 ${fmt(next.ytSubs)}\uBA85`);
        }
        if (prev.ytViews != null && next.ytViews - prev.ytViews >= 1e3) alerts.push(`\u{1F441} \uC870\uD68C\uC218 +${fmt(next.ytViews - prev.ytViews)} \u2192 ${fmt(next.ytViews)}`);
      }
    }
    if (c.paypalClientId && c.paypalSecret) {
      const r = await fetchRevenue(c.paypalClientId, c.paypalSecret, { days: 7 }).catch(() => null);
      const t = r?.data?.totals;
      const cur = t?.primary_currency || Object.keys(t?.by_currency || {})[0];
      const cc2 = cur ? t.by_currency[cur] : null;
      if (cc2) {
        next.payCount = cc2.count;
        next.payNet = (cc2.gross || 0) + (cc2.refunds || 0) + (cc2.fees || 0);
        if (prev.payCount != null && next.payCount > prev.payCount) alerts.push(`\u{1F4B0} \uC0C8 \uACB0\uC81C ${next.payCount - prev.payCount}\uAC74! 7\uC77C \uC21C\uB9E4\uCD9C ${fmt(next.payNet)} ${cur}`);
      }
    }
    const g = connOf("github");
    if (g.GITHUB_TOKEN && g.GITHUB_DEFAULT_REPO) {
      const gh = await listCommits(g.GITHUB_TOKEN, g.GITHUB_DEFAULT_REPO, 1).catch(() => null);
      const top = gh?.commits?.[0];
      if (top) {
        next.ghSha = top.sha;
        if (prev.ghSha && prev.ghSha !== top.sha) alerts.push(`\u{1F4BB} \uC0C8 \uCEE4\uBC0B: ${top.msg.split("\n")[0].slice(0, 60)}`);
      }
    }
    if (!c.emailAutoReply) {
      const e = (c.apiConn || {}).email || {};
      if (e.SMTP_USER && e.SMTP_PASS) {
        const host = e.IMAP_HOST || (e.SMTP_HOST || "").replace(/^smtp\./, "imap.") || "imap.gmail.com";
        const m = await fetchUnseen({ host, port: e.IMAP_PORT || "993", user: e.SMTP_USER, pass: e.SMTP_PASS }, 5).catch(() => null);
        if (m?.ok) {
          next.mails = (m.mails || []).length;
          if (prev.mails != null && next.mails > prev.mails) alerts.push(`\u{1F4E7} \uC0C8 \uBA54\uC77C ${next.mails - prev.mails}\uD1B5 \u2014 "${(m.mails[0]?.subject || "").slice(0, 40)}"`);
        }
      }
    }
    try {
      fs8.writeFileSync(monFile(), JSON.stringify(next));
    } catch {
    }
    if (alerts.length && prev.t) {
      await tgSend(`\u{1F6F0}\uFE0F ${c.company || "\uD68C\uC0AC"} \uC790\uC0B0 \uBCC0\uD654 \uAC10\uC9C0
${alerts.join("\n")}

"\uC6B4\uC601" \uC774\uB77C\uACE0 \uB2F5\uD558\uBA74 \uBC14\uB85C \uB300\uC751 \uC791\uC804\uC744 \uC9ED\uB2C8\uB2E4.`);
      for (const al of alerts) {
        opsState.feed.unshift({ icon: "\u{1F6F0}\uFE0F", text: al.slice(0, 64), agent: "secretary", ok: true, ts: Date.now() });
      }
      opsState.feed = opsState.feed.slice(0, 40);
      opsEmitLight();
      notify("\u{1F6F0}\uFE0F \uC790\uC0B0 \uBCC0\uD654 \uAC10\uC9C0", alerts[0]);
    }
  } finally {
    monBusy = false;
  }
}
