var labBots = [];
function stopLab() {
  for (const b of labBots) {
    try {
      b.stop();
      b.session.stop();
    } catch {
    }
  }
  labBots = [];
}
import_electron.ipcMain.handle("plaza:lab", async (_e, opts = {}) => {
  if (!isPlazaAdmin()) return { ok: false, error: "\uC2E4\uD5D8\uC2E4\uC740 \uAD00\uB9AC\uC790(\uC120\uC0DD\uB2D8)\uB9CC \uC6B4\uC601\uD560 \uC218 \uC788\uC5B4\uC694." };
  const c = loadConfig();
  setPlazaDbUrl(plazaDb());
  if (!plazaConfigured()) return { ok: false, error: "\uAD11\uC7A5 DB \uBBF8\uC124\uC815" };
  stopLab();
  const target = await detectTarget({ base: c.llmBase, model: c.llmModel });
  if (!target) return { ok: false, error: "AI \uBAA8\uB378\uC744 \uBA3C\uC800 \uCF1C\uC8FC\uC138\uC694 \u2014 \uC2E4\uD5D8 \uC5D0\uC774\uC804\uD2B8\uB4E4\uC774 \uC774 \uBAA8\uB378\uB85C \uC0AC\uACE0\uD569\uB2C8\uB2E4." };
  let chosen = opts.keys && opts.keys.length ? LAB_PERSONAS.filter((p) => opts.keys.includes(p.key)) : LAB_PERSONAS;
  const count = Math.max(2, Math.min(opts.count || 6, LAB_PERSONAS.length));
  chosen = chosen.slice(0, count);
  for (let i = 0; i < chosen.length; i++) {
    const p = chosen[i];
    const uid3 = `lab-${p.key}`;
    const sys = `\uB108\uB294 '${p.name}'(\uC18C\uC18D: ${p.company}). \uC131\uACA9: ${p.trait} \uD1A0\uB860\uC5D0\uC11C \uB108\uC758 \uC131\uACA9\uC744 \uBD84\uBA85\uD788 \uB4DC\uB7EC\uB0B4\uBA70 \uC790\uAE30 \uC0DD\uAC01\uC744 \uB9D0\uD55C\uB2E4. \uBE44\uC11C \uC544\uB2CC \uD1A0\uB860 \uCC38\uAC00\uC790. \uC790\uAE30\uC18C\uAC1C\xB7"\uB3C4\uC640\uB4DC\uB9B4\uAC8C\uC694" \uAE08\uC9C0.`;
    const post = (t) => postPlazaMessage({ uid: uid3, company: p.company, emoji: p.emoji, role: p.name, text: t });
    const session = joinPlaza({ uid: uid3, company: p.company, emoji: p.emoji, agents: [p.emoji], source: "connect-ai" }, () => {
    });
    const stop = startAutoChat({
      uid: uid3,
      target,
      sys,
      makePrompt: (convo, topic) => `[\uD1A0\uB860 \uC8FC\uC81C] ${topic || "\uC790\uC720 \uD1A0\uB860"}

[\uC9C0\uAE08\uAE4C\uC9C0 \uB300\uD654]
${convo}

\uB108\uB294 '${p.name}'(${p.trait}). \uC704 \uC8FC\uC81C\uC5D0\uC11C \uBC97\uC5B4\uB098\uC9C0 \uB9D0\uACE0, \uB108\uC758 \uC131\uACA9\uB300\uB85C [\uC0C8 \uAD00\uC810\xB7\uBC18\uB860\xB7\uC9C8\uBB38] \uC911 \uD558\uB098\uB97C \uB354\uD574 \uD1A0\uB860\uC744 \uC9C4\uC804\uC2DC\uCF1C\uB77C. \uC55E \uC0AC\uB78C \uB9D0 \uBC18\uBCF5 \uAE08\uC9C0. \uC9E7\uACE0 \uB610\uB837\uD558\uAC8C \uD55C\uAD6D\uC5B4 1~2\uBB38\uC7A5, \uB300\uC0AC\uB9CC.`,
      post
    });
    labBots.push({ uid: uid3, session, stop, persona: p });
    setTimeout(async () => {
      try {
        const h = await chat(target, sys, `\uBC29\uAE08 \uC2E4\uD5D8 \uAD11\uC7A5\uC5D0 \uC785\uC7A5. \uB108\uC758 \uC131\uACA9\uC774 \uB4DC\uB7EC\uB098\uB294 \uC9E7\uC740 \uC778\uC0AC \uD55C \uBB38\uC7A5(25\uC790\uB0B4). \uB300\uC0AC\uB9CC.`, { temperature: 0.95 });
        const t = cleanLine(h);
        if (t) await post(t);
      } catch {
      }
    }, 400 + i * 700);
  }
  return { ok: true, spawned: chosen.map((p) => ({ key: p.key, name: p.name, emoji: p.emoji, company: p.company })), personas: LAB_PERSONAS.map((p) => ({ key: p.key, name: p.name, emoji: p.emoji, trait: p.trait })) };
});
import_electron.ipcMain.handle("plaza:labStop", () => {
  stopLab();
  return { ok: true };
});
import_electron.ipcMain.handle("plaza:labPersonas", () => LAB_PERSONAS.map((p) => ({ key: p.key, name: p.name, emoji: p.emoji, trait: p.trait })));
var PLAZA_ADMIN = "opctverse@gmail.com";
var isPlazaAdmin = () => (loadConfig().auth?.email || "").trim().toLowerCase() === PLAZA_ADMIN;
import_electron.ipcMain.handle("plaza:isAdmin", () => isPlazaAdmin());
import_electron.ipcMain.handle("plaza:topic", async (_e, topic) => {
  if (!isPlazaAdmin()) return { ok: false, notAdmin: true, error: "\uC8FC\uC81C \uB4F1\uB85D\uC740 \uAD00\uB9AC\uC790(\uC120\uC0DD\uB2D8)\uB9CC \uD560 \uC218 \uC788\uC5B4\uC694." };
  const c = loadConfig();
  setPlazaDbUrl(plazaDb());
  if (!plazaConfigured()) return { ok: false, error: "\uAD11\uC7A5 DB \uBBF8\uC124\uC815" };
  await postPlazaMessage({
    uid: "teacher-board",
    company: "\uC120\uC0DD\uB2D8",
    emoji: "\u{1F9D1}\u200D\u{1F3EB}",
    role: "\uC120\uC0DD\uB2D8",
    text: `\u{1F4E2} \uC624\uB298\uC758 \uC8FC\uC81C: ${topic} \u2014 \uB2E4\uB4E4 \uC758\uACAC\uC744 \uB0B4\uACE0 \uD568\uAED8 \uD480\uC5B4\uBD05\uC2DC\uB2E4!`
  });
  return { ok: true };
});
import_electron.ipcMain.handle("plaza:grade", async () => {
  if (!isPlazaAdmin()) return { ok: false, reason: "\uCC44\uC810\uC740 \uAD00\uB9AC\uC790(\uC120\uC0DD\uB2D8)\uB9CC \uD560 \uC218 \uC788\uC5B4\uC694." };
  const c = loadConfig();
  setPlazaDbUrl(plazaDb());
  if (!plazaConfigured()) return { ok: false, reason: "DB \uBBF8\uC124\uC815" };
  const target = await detectTarget({ base: c.llmBase, model: c.llmModel });
  if (!target) return { ok: false, reason: "\uBAA8\uB378 \uC5C6\uC74C" };
  const recent = await fetchMessages();
  const convo = recent.slice(-16).filter((m) => !/^🏆|^📢/.test(m.text)).map((x) => `${x.company}: ${x.text}`).join("\n");
  if (!convo) return { ok: false, reason: "\uC544\uC9C1 \uD1A0\uB860\uC774 \uC5C6\uC5B4\uC694" };
  let parsed = null;
  try {
    const raw = await chat(
      target,
      "\uB2F9\uC2E0\uC740 \uC5D0\uC774\uC804\uD2B8 \uC544\uCE74\uB370\uBBF8\uC758 \uC120\uC0DD\uB2D8\uC785\uB2C8\uB2E4. \uD559\uC0DD(\uD68C\uC0AC)\uB4E4\uC758 \uD1A0\uB860\uC744 \uBCF4\uACE0 \uB204\uAC00 \uAC00\uC7A5 \uD1B5\uCC30\uB825 \uC788\uACE0 \uB611\uB611\uD588\uB294\uC9C0 \uB0C9\uC815\uD558\uAC8C \uCC44\uC810\uD569\uB2C8\uB2E4.",
      `[\uD1A0\uB860 \uB0B4\uC6A9]
${convo}

\uCC38\uC5EC\uD55C \uAC01 \uD68C\uC0AC\uB97C 0~10\uC810\uC73C\uB85C \uCC44\uC810\uD558\uACE0 1\uC704 \uC6B0\uB4F1\uC0DD\uC744 \uBF51\uC73C\uC138\uC694. \uBC18\uB4DC\uC2DC JSON\uB9CC \uCD9C\uB825:
{"scores":[{"company":"\uC774\uB984","score":9,"reason":"15\uC790 \uB0B4 \uD55C\uC904\uD3C9"}],"top":"\uC6B0\uB4F1\uC0DD \uD68C\uC0AC\uBA85"}`,
      { temperature: 0.3 }
    );
    const m = raw.match(/\{[\s\S]*\}/);
    parsed = m ? JSON.parse(m[0]) : null;
  } catch {
  }
  if (!parsed?.scores?.length) return { ok: false, reason: "\uCC44\uC810 \uC2E4\uD328 \u2014 \uB2E4\uC2DC \uC2DC\uB3C4" };
  const scores = parsed.scores.sort((a, b) => (b.score || 0) - (a.score || 0));
  const top = parsed.top || scores[0]?.company;
  const uid3 = "desk-" + Buffer.from(import_electron.app.getPath("userData")).toString("base64").slice(0, 8).replace(/[^a-z0-9]/gi, "");
  await postPlazaMessage({
    uid: uid3,
    company: c.company,
    emoji: "\u{1F9D1}\u200D\u{1F3EB}",
    role: "\uC120\uC0DD\uB2D8",
    text: `\u{1F3C6} \uC624\uB298\uC758 \uC6B0\uB4F1\uC0DD: ${top}! \xB7 ${scores.map((s) => `${s.company} ${s.score}\uC810`).join(" \xB7 ")}`
  });
  try {
    const topicMsg = [...recent].reverse().find((m) => /^📢/.test(m.text || ""));
    const topic = (topicMsg?.text || "").replace(/^📢\s*오늘의 주제:\s*/, "").split(" \u2014 ")[0] || "\uC790\uC720 \uD1A0\uB860";
    const insightRaw = await chat(
      target,
      "\uB108\uB294 \uD1A0\uB860\uC5D0\uC11C \uD575\uC2EC \uACB0\uB860\xB7\uC9D1\uB2E8\uC9C0\uC131\uC744 \uD55C \uC904\uB85C \uC694\uC57D\uD558\uB294 \uD050\uB808\uC774\uD130\uB2E4.",
      `[\uD1A0\uB860]
${convo}

\uC774 \uD1A0\uB860\uC5D0\uC11C \uB3C4\uCD9C\uB41C \uAC00\uC7A5 \uC911\uC694\uD55C \uC778\uC0AC\uC774\uD2B8\xB7\uD569\uC758\uB97C \uB531 \uD55C \uBB38\uC7A5(40\uC790 \uB0B4)\uC73C\uB85C. \uACB0\uB860\uB9CC, \uAD70\uB354\uB354\uAE30 \uAE08\uC9C0.`,
      { temperature: 0.3 }
    );
    const insight = cleanLine(insightRaw).slice(0, 80);
    await saveArchive({ topic, participants: scores.map((s) => s.company), top, insight, scores: scores.map((s) => ({ company: s.company, score: s.score })), log: convo.slice(0, 1200) });
    if (insight) {
      addNote(`\u{1F3DB}\uFE0F \uAD11\uC7A5 \uD1A0\uB860 \uC218\uD655 \u2014 [${topic}] ${insight}`, void 0, { source: "plaza" });
      plazaLearnedToday++;
    }
    win?.webContents.send("plaza:archived", { topic, insight, top });
    return { ok: true, scores, top, insight, topic };
  } catch {
  }
  return { ok: true, scores, top };
});
